function icon(name,size=18,cls=''){return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||''}</svg>`}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function href(path){return path}
function link(path,label,cls=''){return `<a href="${path}" class="${cls}">${label}</a>`}
function sectionHead(eyebrow,title,copy=''){return `<div class="section-head"><span class="eyebrow">${eyebrow}</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>`}
function pageHero(eyebrow,title,copy){return `<section class="page-hero"><div class="container"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div></section>`}

function header(){
 const dropItems=services.map(s=>`<a href="/services/${s.slug}" role="menuitem"><span>${s.num}</span>${s.title}</a>`).join('');
 return `<header class="header" id="site-header"><div class="nav container"><a class="brand" href="/"><img src="${A}tervoxa-mark.jpeg" alt="Tervoxa Technologies"><span><b>TERVOXA</b><small>TECHNOLOGIES</small></span></a><nav class="desktop-nav" aria-label="Primary navigation"><a href="/">Home</a><a href="/about">About</a><div class="nav-drop"><button type="button" id="services-toggle" aria-expanded="false">Services ${icon('chevronDown',15)}</button><div class="mega" id="services-menu" role="menu" hidden>${dropItems}</div></div><a href="/process">Process</a><a href="/faq">FAQs</a><a href="/contact">Contact</a></nav><button class="menu-btn" type="button" id="menu-toggle" aria-label="Toggle navigation" aria-expanded="false">${icon('menu',24)}</button></div><div class="mobile-menu" id="mobile-menu" hidden><a href="/">Home</a><a href="/about">About</a><a href="/services">Services</a><a href="/process">Process</a><a href="/faq">FAQs</a><a href="/contact">Contact</a></div></header>`;
}
function footer(){return `<footer><div class="container footer-grid"><div><a class="brand footer-brand" href="/"><img src="${A}tervoxa-mark.jpeg" alt="Tervoxa Technologies"><span><b>TERVOXA</b><small>TECHNOLOGIES</small></span></a><p>Technology. Vision. Value.</p><p class="muted">Building digital solutions for modern businesses.</p></div><div><h4>Services</h4>${services.map(s=>link(`/services/${s.slug}`,s.title)).join('')}</div><div><h4>Company</h4>${link('/about','About Us')}${link('/services','Services')}${link('/process','Our Process')}${link('/faq','FAQs')}</div><div><h4>Contact</h4><p class="muted">Have a project or requirement?</p><a class="footer-link" href="/contact">Start a project enquiry ${icon('arrowUpRight',15)}</a></div></div><div class="container footer-bottom"><span>© 2026 Tervoxa Technologies. All Rights Reserved.</span><div>${link('/privacy-policy','Privacy Policy')}${link('/terms','Terms & Conditions')}${link('/disclaimer','Disclaimer')}</div><b>Build • Protect • Support</b></div></footer>`}

function layout(content){return `<div class="app">${header()}<main>${content}</main>${footer()}</div>`}
function finalCTA(){return `<section class="final-cta"><div class="container"><span class="eyebrow">Start a project</span><h2>Tell us what you are trying to achieve.</h2><p>Bring us a new idea, an existing process, a security concern or technical work that needs a dependable next step.</p><strong>Build. Protect. Support.</strong><a class="button light" href="/contact">Get in touch ${icon('arrowRight',18)}</a></div></section>`}

