function why(){const data=[['We listen first','We start with the situation you are in, not with a package we are trying to sell.'],['The scope stays visible','You know what is included, what is not and what decisions are still needed.'],['The right people are involved','We bring technology, security, business and design into the conversation when the work calls for it.'],['Security is handled responsibly','Assessments and testing are carried out with the right authorisation and care.'],['The result has to be usable','The finished work should make sense to the people who use and maintain it.'],['You get a straight answer','We keep communication clear, including when a different approach would be better.'],['The work can continue','Where useful, we plan for updates, maintenance and the next stage after delivery.']];return `<section class="section dark"><div class="container">${sectionHead('What you can expect','A straightforward way to work together')}<div class="why-grid">${data.map((x,i)=>`<div class="why-item"><span>0${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div></div></section>`}
