<section class="section about-pillars"><div class="container">${sectionHead('Our role','From the first requirement to the next stage of growth.','Different projects need different combinations of capability. Our role is to bring the right focus to the work at the right time.')}<div class="about-pillar-grid">${pillars.map(p=>`<article class="about-pillar"><div class="about-pillar-top"><span>${p[1]}</span>${icon(p[0],28)}</div><h3>${p[2]}</h3><p>${p[3]}</p></article>`).join('')}</div></div></section>
