<section class="section about-method"><div class="container">${sectionHead('How we think','Good delivery is more than a finished screen.','The quality of a solution is also measured by how clearly it was scoped, how responsibly it was built and how well it serves the people using it.')}<div class="about-principles">${principles.map((p,i)=>`<div><b>${String(i+1).padStart(2,'0')}</b><div><h3>${p[0]}</h3><p>${p[1]}</p></div></div>`).join('')}</div></div></section>
